type SearchParams = Record<string, string | string[] | undefined>;
const SORTS = ["newest", "price-asc", "price-desc"];

function parseFilters(sp: SearchParams) {
  const q = typeof sp.q === "string" ? sp.q.trim() : "";
  const n = parseInt(String(sp.page ?? ""), 10);
  const page = Number.isInteger(n) && n >= 1 ? n : 1;
  const sort = typeof sp.sort === "string" && SORTS.includes(sp.sort) ? sp.sort : "newest";
  const raw = sp.tag === undefined ? [] : Array.isArray(sp.tag) ? sp.tag : [sp.tag];
  const tags = [...new Set(raw.filter((t) => t !== ""))];
  return { q, page, sort, tags };
}

