function rank(segment) {
  if (segment.startsWith("[[...")) return 0;
  if (segment.startsWith("[...")) return 1;
  if (segment.startsWith("[")) return 2;
  return 3;
}

function resolveRoute(routes, path) {
  const scored = routes
    .filter((r) => matches(r, path))
    .map((r) => ({ r, score: r.split("/").filter(Boolean).map(rank) }));
  scored.sort((a, b) => {
    const len = Math.max(a.score.length, b.score.length);
    for (let i = 0; i < len; i++) {
      const x = a.score[i] ?? -1;
      const y = b.score[i] ?? -1;
      if (x !== y) return y - x;
    }
    return 0;
  });
  return scored.length ? scored[0].r : null;
}

