function localeRedirect(pathname, acceptLanguage, locales, defaultLocale) {
  if (locales.some((l) => pathname.startsWith("/" + l))) return null;
  const wanted = acceptLanguage
    .split(",")
    .map((part) => part.split(";")[0].trim().toLowerCase())
    .filter(Boolean);
  const locale = wanted.find((l) => locales.includes(l)) ?? defaultLocale;
  return "/" + locale + (pathname === "/" ? "" : pathname);
}

